(x, y, t) => {
  const cx = 240, cy = 120;
  const src = [
    [160 + Math.sin(t*0.6)*100, 80 + Math.cos(t*0.4)*50],
    [320 + Math.cos(t*0.5)*100, 160 + Math.sin(t*0.7)*50],
    [240 + Math.sin(t*0.3+2)*140, 120 + Math.cos(t*0.5+1)*90],
    [120 + Math.cos(t*0.8+1)*80, 180 + Math.sin(t*0.35+3)*70],
    [360 + Math.sin(t*0.45+4)*90, 60 + Math.cos(t*0.65+2)*80]
  ];
  const freqs = [0.08, 0.1, 0.06, 0.09, 0.07];
  const speeds = [2, 1.7, 2.3, 1.9, 2.5];
  let waves = 0;
  for (let i = 0; i < 5; i++) {
    const d = Math.sqrt((x - src[i][0])**2 + (y - src[i][1])**2);
    waves += Math.sin(d * freqs[i] - t * speeds[i]) / (1 + d * 0.003);
  }
  waves /= 5;
  const wx = Math.sin(x*0.02 + t*0.3)*15 + Math.cos(y*0.03 - t*0.2)*10;
  const wy = Math.cos(x*0.025 - t*0.25)*12 + Math.sin(y*0.02 + t*0.35)*15;
  const wx2 = Math.sin((x+wx)*0.015 + t*0.15)*20;
  const wy2 = Math.cos((y+wy)*0.018 - t*0.2)*20;
  const field1 = Math.sin((x+wx+wx2)*0.05 + (y+wy+wy2)*0.03 + t*0.8);
  const field2 = Math.sin((x+wx)*0.03 - (y+wy)*0.05 + t*1.1);
  const field3 = Math.sin((x+y)*0.15 + t*3)*0.15;
  const field4 = Math.sin((x-y)*0.12 - t*2.5)*0.15;
  const activator = waves;
  const inhibitor = (field1 + field2) / 2;
  const reaction1 = Math.tanh((activator - inhibitor*0.8 + field3 + field4)*2.5);
  const dist = Math.sqrt((x-cx)**2 + (y-cy)**2);
  const ang = Math.atan2(y-cy, x-cx);
  const radial = Math.sin(dist*0.04 - t*1.5);
  const angular = Math.sin(ang*6 + t*0.4);
  const spiral = Math.sin(ang*3 - dist*0.02 + t*0.6);
  const reaction2 = Math.tanh((radial + angular*0.5 + spiral*0.3)*2);
  const micro = Math.sin(x*0.2 + y*0.15 + Math.sin(x*0.1 - t)*2) *
                Math.cos(y*0.18 - x*0.12 + Math.cos(y*0.08 + t)*2)*0.3;
  const sb = 0.5 + Math.sin(dist*0.02 + t*0.3)*0.2;
  const blend = reaction1*sb + reaction2*(1-sb) + micro*0.15;
  const v = blend*0.5 + 0.5;
  const pal = [
    [8,15,58],[15,72,108],[28,138,145],[75,185,160],
    [218,195,85],[225,145,65],[200,85,65],[135,40,75],[55,20,65],[8,15,58]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const sf = f*f*(3 - 2*f);
  const lum = 0.88 + Math.sin(blend*Math.PI*1.5)*0.12;
  const eg = Math.pow(Math.abs(Math.sin(blend*Math.PI)), 3)*0.12;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum + eg*220))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum + eg*180))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum + eg*130))|0
  ];
}
